RESULT = False
VERDICT = "FAIL"


def gcd(a: int, b: int) -> int:
    while b:
        a, b = b, a % b
    return a


def feasible(a: int, b: int, c: int) -> bool:
    g1 = gcd(a, b)
    g2 = gcd(a, c)
    g3 = gcd(b, c)
    return not (g1 == g2 and g2 == g3)


def feasible_set(S) -> bool:
    n = len(S)
    for i in range(n):
        for j in range(i + 1, n):
            for k in range(j + 1, n):
                if not feasible(S[i], S[j], S[k]):
                    return False
    return True


def subsets(universe, size):
    n = len(universe)
    idx = list(range(size))
    while True:
        yield [universe[i] for i in idx]
        i = size - 1
        while i >= 0 and idx[i] == n - size + i:
            i -= 1
        if i < 0:
            return
        idx[i] += 1
        for j in range(i + 1, size):
            idx[j] = idx[j - 1] + 1


def f3(N: int) -> int:
    universe = list(range(1, N + 1))
    for size in range(N, 0, -1):
        for S in subsets(universe, size):
            if feasible_set(S):
                return size
    return 0


def verify() -> bool:
    expected = [1, 2, 2, 3, 3, 3, 3]
    if len(expected) != 7:
        return False
    for N in range(1, 8):
        if f3(N) != expected[N - 1]:
            return False
    return True


RESULT = verify()
if RESULT:
    VERDICT = "PASS"
